                    }
                    catch
                    {
                    }
                    finally
                    {
                        m.ReleaseMutex();
                    }
                }
            })();
            Editor.KeyDown += OnEditorKeyDownForZoom;
            new System.Action(() =>
            {
                using var m = new System.Threading.Mutex(false, @"Global\sbfl_coverage_lock");
                if (m.WaitOne(3000))
                {
                    try
                    {
                        System.IO.File.AppendAllText("C:\\Repos\\CSharpFLPublic\\SBFLApp\\bin\\Debug\\net10.0\\Coverage\\__sbfl_current_test.coverage.tmp", "39c28000-2549-4020-ba57-df1700d87929" + System.Environment.NewLine);
                    }
                    catch
                    {
                    }
                    finally
                    {
                        m.ReleaseMutex();
                    }
                }
            })();
            // Ctrl+C copies as text + syntax-coloured HTML so a paste into an HTML target keeps the
            // highlighting. Tunnel so we run before AvaloniaEdit's plain-text copy keybinding and can
            // suppress it; falls through (Handled stays false) when there's no selection.
            Editor.AddHandler(InputElement.KeyDownEvent, OnEditorKeyDownForCopy, RoutingStrategies.Tunnel, handledEventsToo: false);
        }

