                    }
                    catch
                    {
                    }
                    finally
                    {
                        m.ReleaseMutex();
                    }
                }
            })();
            return folding.Tag is DefinitionNewFolding definition ? Math.Min(definition.DefinitionStartOffset, folding.StartOffset) : folding.StartOffset;
        }

