        // The token + assembly identity that ties a bookmark to a member in the current document. The
        // module identity is checked too, so a token value shared across assemblies can't match the
        // wrong member. Both forms (the body-anchor debug map and a reference segment's entity) are
        // kept in step here rather than spelled out at each call site.
        static bool MatchesBookmark(Bookmarks.MethodDebugInfo method, Bookmarks.Bookmark bookmark) => method.Token == bookmark.Token && method.AssemblyFullName == bookmark.AssemblyFullName;
        static bool MatchesBookmark(IEntity entity, Bookmarks.Bookmark bookmark) => (uint)MetadataTokens.GetToken(entity.MetadataToken) == bookmark.Token && entity.ParentModule?.MetadataFile?.FullName == bookmark.AssemblyFullName;
