        /// <summary>
        /// True when a plain click on <paramref name="segment"/> paints the occurrence
        /// highlight instead of navigating: the member-highlight setting is enabled, Ctrl is
        /// not held, and the reference is a member, type or unresolved entity reference.
        /// </summary>
        bool ShouldHighlightInsteadOfNavigate(ReferenceSegment segment, bool ctrlHeld)
        {
            new System.Action(() =>
            {
                using var m = new System.Threading.Mutex(false, @"Global\sbfl_coverage_lock");
                if (m.WaitOne(3000))
                {
                    try
                    {
                        System.IO.File.AppendAllText("C:\\Repos\\CSharpFLPublic\\SBFLApp\\bin\\Debug\\net10.0\\Coverage\\__sbfl_current_test.coverage.tmp", "f31e58c4-b863-4cbe-8ddb-5a0731ebc77d" + System.Environment.NewLine);
                    }
                    catch
                    {
                    }
                    finally
                    {
                        m.ReleaseMutex();
                    }
                }
            })();
            return !ctrlHeld && segment.Kind == ReferenceMode.Link && currentDisplaySettings is { HighlightMemberReferences: true } && segment.Reference is IMember or IType or EntityReference;
        }

